import AppKit
import SwiftUI
import TernCore

/// One stroke or fill of an icon on the 24×24 grid (see `Hugeicons.swift`, generated by
/// scripts/hugeicons.py).
struct IconPart: Sendable {
    let data: String
    /// Stroke width on the 24 grid; 0 when the part is only filled.
    let stroke: CGFloat
    let filled: Bool

    init(_ data: String, stroke: CGFloat, filled: Bool = false) {
        self.data = data
        self.stroke = stroke
        self.filled = filled
    }
}

extension Icon {
    /// A parsed part, ready to draw.
    struct Drawing {
        let path: CGPath
        let stroke: CGFloat
        let filled: Bool
    }

    /// The parts as paths on the 24 grid, parsed once.
    var shapes: [Drawing] { IconCache.shapes(self) }

    /// The icon for a project's stored symbol name (projects keep the SF Symbol name they were made with).
    static func project(_ name: String?) -> Icon {
        switch name {
        case "paperplane": .paperplane
        case "paintpalette": .palette
        case "house": .house
        case "briefcase": .briefcase
        case "hammer": .hammer
        case "book": .book
        case "heart": .heart
        case "airplane": .airplane
        case "cart": .cart
        case "graduationcap": .graduation
        case "leaf": .newsletter
        default: .folder
        }
    }

    /// The icon a category's tab and tag use.
    static func category(_ category: MailCategory) -> Icon {
        switch category {
        case .people: .people
        case .notification: .notification
        case .newsletter: .newsletter
        case .receipt: .receipt
        case .calendar: .calendar
        case .promotion: .promotion
        case .security: .security
        case .other: .other
        }
    }

    /// Inline SVG markup in `currentColor`, for the reader page (Tern's own chrome, never mail content).
    var svgMarkup: String {
        var body = ""
        for part in parts {
            let stroke = part.stroke > 0 ? " stroke=\"currentColor\" stroke-width=\"\(part.stroke)\"" : ""
            body += "<path d=\"\(part.data)\" fill=\"\(part.filled ? "currentColor" : "none")\"\(stroke)/>"
        }
        return "<svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\(body)</svg>"
    }

    /// The icon as a template image, for places that only take images (menu items, SwiftUI `Menu` labels).
    func image(size: CGFloat = 16, weight: CGFloat = 1) -> NSImage {
        let image = NSImage(size: NSSize(width: size, height: size), flipped: true) { rect in
            self.draw(in: rect, color: .black, weight: weight)
            return true
        }
        image.isTemplate = true
        return image
    }

    /// Draws the icon into the current AppKit graphics context (flipped views). `weight` scales the
    /// stroke: 1 is Hugeicons' 1.5 on the 24 grid.
    func draw(in rect: CGRect, color: NSColor, weight: CGFloat = 1) {
        guard let context = NSGraphicsContext.current?.cgContext else { return }
        let scale = min(rect.width, rect.height) / 24
        context.saveGState()
        context.translateBy(x: rect.minX, y: rect.minY)
        context.scaleBy(x: scale, y: scale)
        context.setStrokeColor(color.cgColor)
        context.setFillColor(color.cgColor)
        context.setLineCap(.round)
        context.setLineJoin(.round)
        for shape in shapes {
            if shape.filled {
                context.addPath(shape.path)
                context.fillPath()
            }
            if shape.stroke > 0 {
                context.addPath(shape.path)
                context.setLineWidth(shape.stroke * weight)
                context.strokePath()
            }
        }
        context.restoreGState()
    }
}

/// Parses each icon the first time it is drawn. Drawing can happen off the main thread (image reps),
/// so the cache is locked.
private enum IconCache {
    private static let lock = NSLock()
    nonisolated(unsafe) private static var parsed: [Icon: [Icon.Drawing]] = [:]

    static func shapes(_ icon: Icon) -> [Icon.Drawing] {
        lock.lock()
        defer { lock.unlock() }
        if let shapes = parsed[icon] { return shapes }
        let shapes = icon.parts.map { Icon.Drawing(path: SVGPath.parse($0.data), stroke: $0.stroke, filled: $0.filled) }
        parsed[icon] = shapes
        return shapes
    }
}

/// A Hugeicons icon for SwiftUI, tinted with `color`.
struct IconView: View {
    let icon: Icon
    var size: CGFloat = 16
    var color: Color = Color(Theme.text2)
    /// Stroke multiplier; 1 is the icon set's own weight.
    var weight: CGFloat = 1

    var body: some View {
        Canvas { context, canvas in
            let scale = min(canvas.width, canvas.height) / 24
            let transform = CGAffineTransform(scaleX: scale, y: scale)
            for shape in icon.shapes {
                let path = Path(shape.path).applying(transform)
                if shape.filled { context.fill(path, with: .color(color)) }
                if shape.stroke > 0 {
                    context.stroke(path, with: .color(color),
                                   style: StrokeStyle(lineWidth: shape.stroke * weight * scale, lineCap: .round, lineJoin: .round))
                }
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}

/// Minimal SVG path-data parser: M L H V C S Q A Z, absolute and relative.
enum SVGPath {
    static func parse(_ data: String) -> CGPath {
        let path = CGMutablePath()
        var scanner = Tokens(data)
        var current = CGPoint.zero
        var start = CGPoint.zero
        var lastControl: CGPoint?
        var command: Character = "M"

        while let next = scanner.peekCommandOrNumber() {
            if case .command(let c) = next {
                command = c
                scanner.advance()
            }
            let relative = command.isLowercase
            func point() -> CGPoint {
                let x = scanner.number(), y = scanner.number()
                return relative ? CGPoint(x: current.x + x, y: current.y + y) : CGPoint(x: x, y: y)
            }
            switch command.uppercased().first! {
            case "M":
                current = point()
                start = current
                path.move(to: current)
                command = relative ? "l" : "L"
                lastControl = nil
            case "L":
                current = point()
                path.addLine(to: current)
                lastControl = nil
            case "H":
                let x = scanner.number()
                current.x = relative ? current.x + x : x
                path.addLine(to: current)
                lastControl = nil
            case "V":
                let y = scanner.number()
                current.y = relative ? current.y + y : y
                path.addLine(to: current)
                lastControl = nil
            case "C":
                let c1 = point(), c2 = point(), end = point()
                path.addCurve(to: end, control1: c1, control2: c2)
                lastControl = c2
                current = end
            case "S":
                let c1 = lastControl.map { CGPoint(x: 2 * current.x - $0.x, y: 2 * current.y - $0.y) } ?? current
                let c2 = point(), end = point()
                path.addCurve(to: end, control1: c1, control2: c2)
                lastControl = c2
                current = end
            case "Q":
                let c = point(), end = point()
                path.addQuadCurve(to: end, control: c)
                lastControl = c
                current = end
            case "A":
                let rx = scanner.number(), ry = scanner.number(), rotation = scanner.number()
                let large = scanner.flag(), sweep = scanner.flag()
                let end = point()
                addArc(path, from: current, to: end, rx: rx, ry: ry, rotation: rotation, large: large, sweep: sweep)
                current = end
                lastControl = nil
            case "Z":
                path.closeSubpath()
                current = start
                lastControl = nil
                // A number directly after Z would be malformed; skip to the next command.
                if case .number = scanner.peekCommandOrNumber() { scanner.advance() }
            default:
                scanner.advance()
            }
        }
        return path
    }

    /// Endpoint arc to cubic Béziers (SVG 1.1 implementation notes, F.6).
    private static func addArc(_ path: CGMutablePath, from p0: CGPoint, to p1: CGPoint, rx: CGFloat, ry: CGFloat,
                               rotation: CGFloat, large: Bool, sweep: Bool) {
        var rx = abs(rx), ry = abs(ry)
        guard rx > 0, ry > 0, p0 != p1 else { path.addLine(to: p1); return }
        let phi = rotation * .pi / 180
        let cosPhi = cos(phi), sinPhi = sin(phi)
        let dx = (p0.x - p1.x) / 2, dy = (p0.y - p1.y) / 2
        let x1 = cosPhi * dx + sinPhi * dy
        let y1 = -sinPhi * dx + cosPhi * dy
        let lambda = (x1 * x1) / (rx * rx) + (y1 * y1) / (ry * ry)
        if lambda > 1 { rx *= sqrt(lambda); ry *= sqrt(lambda) }
        let num = rx * rx * ry * ry - rx * rx * y1 * y1 - ry * ry * x1 * x1
        let den = rx * rx * y1 * y1 + ry * ry * x1 * x1
        var coef = sqrt(max(0, num / den))
        if large == sweep { coef = -coef }
        let cx1 = coef * rx * y1 / ry
        let cy1 = -coef * ry * x1 / rx
        let cx = cosPhi * cx1 - sinPhi * cy1 + (p0.x + p1.x) / 2
        let cy = sinPhi * cx1 + cosPhi * cy1 + (p0.y + p1.y) / 2

        func angle(_ ux: CGFloat, _ uy: CGFloat, _ vx: CGFloat, _ vy: CGFloat) -> CGFloat {
            let a = atan2(ux * vy - uy * vx, ux * vx + uy * vy)
            return a
        }
        let theta1 = angle(1, 0, (x1 - cx1) / rx, (y1 - cy1) / ry)
        var delta = angle((x1 - cx1) / rx, (y1 - cy1) / ry, (-x1 - cx1) / rx, (-y1 - cy1) / ry)
        if !sweep && delta > 0 { delta -= 2 * .pi }
        if sweep && delta < 0 { delta += 2 * .pi }

        let segments = max(1, Int(ceil(abs(delta) / (.pi / 2))))
        let step = delta / CGFloat(segments)
        let t = 4 / 3 * tan(step / 4)
        var theta = theta1
        func pointAt(_ a: CGFloat) -> CGPoint {
            let x = rx * cos(a), y = ry * sin(a)
            return CGPoint(x: cosPhi * x - sinPhi * y + cx, y: sinPhi * x + cosPhi * y + cy)
        }
        func derivative(_ a: CGFloat) -> CGPoint {
            let x = -rx * sin(a), y = ry * cos(a)
            return CGPoint(x: cosPhi * x - sinPhi * y, y: sinPhi * x + cosPhi * y)
        }
        for _ in 0..<segments {
            let a = pointAt(theta), b = pointAt(theta + step)
            let da = derivative(theta), db = derivative(theta + step)
            path.addCurve(
                to: b,
                control1: CGPoint(x: a.x + t * da.x, y: a.y + t * da.y),
                control2: CGPoint(x: b.x - t * db.x, y: b.y - t * db.y))
            theta += step
        }
    }

    private struct Tokens {
        enum Token { case command(Character), number }
        let chars: [Character]
        var index = 0

        init(_ string: String) { chars = Array(string) }

        mutating func skipSeparators() {
            while index < chars.count, chars[index] == " " || chars[index] == "," || chars[index] == "\n" { index += 1 }
        }

        mutating func peekCommandOrNumber() -> Token? {
            skipSeparators()
            guard index < chars.count else { return nil }
            let c = chars[index]
            return c.isLetter ? .command(c) : .number
        }

        mutating func advance() { index += 1 }

        mutating func flag() -> Bool {
            skipSeparators()
            guard index < chars.count else { return false }
            defer { index += 1 }
            return chars[index] == "1"
        }

        mutating func number() -> CGFloat {
            skipSeparators()
            var text = ""
            var seenDot = false, seenExponent = false
            while index < chars.count {
                let c = chars[index]
                if c == "-" || c == "+" {
                    if !text.isEmpty && !(text.last == "e" || text.last == "E") { break }
                } else if c == "." {
                    if seenDot || seenExponent { break }
                    seenDot = true
                } else if c == "e" || c == "E" {
                    seenExponent = true
                } else if !c.isNumber {
                    break
                }
                text.append(c)
                index += 1
            }
            return CGFloat(Double(text) ?? 0)
        }
    }
}
